import { createFileRoute, Link, useRouter } from "@tanstack/react-router";
import { useEffect, useState, type ReactNode, type ButtonHTMLAttributes } from "react";
import { curatiaAuth, type CuratiaSession } from "../lib/curatia-auth";
import { getCuratiaDashboard, updateSignalState, moveSignalToTrendRadar, updateContentStatus, updateContentVisual, generateContentVisual, bootstrapCuratiaUser, getCuratiaOnboarding, completeCuratiaOnboarding, getCuratiaIntegrations, getCuratiaIntegrationAdmin, saveCuratiaIntegrationCatalogItem, verifyCuratiaIntegrationProvider, connectCuratiaIntegration, disconnectCuratiaIntegration, type CuratiaIntegration, type CuratiaIntegrationCatalogItem, type CuratiaOnboarding, type CuratiaContentItem, type CuratiaSignal, type CuratiaDashboard } from "../lib/curatia-content-engine.functions";

export const Route = createFileRoute("/curatia-content-engine")({ loader: () => getCuratiaDashboard(), head: () => ({ meta: [{ title: "Curatia · Editorial Intelligence" }], links: [{ rel: "icon", href: "/curatia-icon.svg", type: "image/svg+xml" }] }), component: Curatia });
type View = "Home"|"Signals"|"Trend Radar"|"Idea Tank"|"Content Pipeline"|"Editorial Studio"|"Calendar"|"Profile"|"Settings"|"Integrations";
const lifecycle = ["Idea","Candidate","Research","Draft","Visual Ready","Approved","Scheduled","Published","Learning"] as const;
const CURATIA_VERSION = "v0.1.0";
declare const __CURATIA_BUILD__: string;
const CURATIA_BUILD = typeof __CURATIA_BUILD__ === "string" ? __CURATIA_BUILD__.slice(0,7) : "local";

function Curatia() {
 const data=Route.useLoaderData(); const router=useRouter(); const [view,setView]=useState<View>("Home"); const [panel,setPanel]=useState<"Profile"|"Settings"|"Integrations"|null>(null); const [panelExpanded,setPanelExpanded]=useState(false); const [busy,setBusy]=useState<string|null>(null);
 const [session,setSession]=useState<CuratiaSession|null>(null); const [integrations,setIntegrations]=useState<CuratiaIntegration[]>([]); const [platformOwner,setPlatformOwner]=useState(false); const [adminCatalog,setAdminCatalog]=useState<CuratiaIntegrationCatalogItem[]>([]); const [authReady,setAuthReady]=useState(false); const [authError,setAuthError]=useState<string|null>(null); const [onboarding,setOnboarding]=useState<CuratiaOnboarding|null>(null); const [accountOpen,setAccountOpen]=useState(false);
 useEffect(()=>{if(!window.history.state?.curatiaView)window.history.replaceState({...window.history.state,curatiaView:"Home"},"");const pop=()=>setView((window.history.state?.curatiaView as View)||"Home");window.addEventListener("popstate",pop);return()=>window.removeEventListener("popstate",pop)},[]);
 useEffect(()=>{if(window.history.state?.curatiaView!==view)window.history.pushState({...window.history.state,curatiaView:view},"")},[view]);
 useEffect(()=>{let alive=true;curatiaAuth.consumeUrl().then(next=>{if(alive){setSession(next);setAuthReady(true)}}).catch(e=>{if(alive){setAuthError(e instanceof Error?e.message:"Authentication failed.");setAuthReady(true)}});const off=curatiaAuth.onChange(next=>setSession(next));return()=>{alive=false;off()}},[]);
 useEffect(()=>{if(!session?.access_token)return;setBusy("bootstrap");bootstrapCuratiaUser({data:{accessToken:session.access_token}}).then(()=>getCuratiaOnboarding({data:{accessToken:session.access_token}})).then(o=>{setOnboarding(o);getCuratiaIntegrations({data:{accessToken:session.access_token}}).then(setIntegrations).catch(()=>setIntegrations([]));getCuratiaIntegrationAdmin({data:{accessToken:session.access_token}}).then(x=>{setPlatformOwner(x.isPlatformOwner);setAdminCatalog(x.catalog)}).catch(()=>{setPlatformOwner(false);setAdminCatalog([])});setAuthError(null)}).catch(e=>setAuthError(e instanceof Error?e.message:"Curatia access failed.")).finally(()=>setBusy(null))},[session?.access_token]);
 async function sendMagicLink(email:string){setBusy("auth");setAuthError(null);try{await curatiaAuth.signInWithOtp(email,window.location.origin+"/curatia-content-engine");setAuthError("Check your email for the Curatia sign-in link.")}catch(e){setAuthError(e instanceof Error?e.message:"Could not send sign-in link.")}finally{setBusy(null)}}
 async function signOut(){await curatiaAuth.signOut();setSession(null)}
 if(!authReady)return <main className="min-h-screen bg-[#f4f0e6] text-[#171717] grid place-items-center"><div className="font-mono text-xs uppercase">Opening Curatia…</div></main>;
 if(!session)return <Login busy={busy==="auth"} message={authError} send={sendMagicLink} oauth={provider=>curatiaAuth.signInWithOAuth(provider,window.location.origin+"/curatia-content-engine")}/>;
 if(authError && !authError.startsWith("Check"))return <Login busy={false} message={authError} send={sendMagicLink} oauth={provider=>curatiaAuth.signInWithOAuth(provider,window.location.origin+"/curatia-content-engine")}/>;
 async function finishOnboarding(value:CuratiaOnboarding){if(!session)return;setBusy("onboarding");setAuthError(null);try{await completeCuratiaOnboarding({data:{accessToken:session.access_token,displayName:value.displayName,roleTitle:value.roleTitle,bio:value.bio,workspaceName:value.workspaceName,contentTerritories:value.contentTerritories,primaryAudience:value.primaryAudience,secondaryAudiences:value.secondaryAudiences,audienceOutcomes:value.audienceOutcomes,languages:value.languages,interests:value.interests,baselines:value.baselines,watchlists:[],channels:value.channels as any,primaryChannel:value.primaryChannel as any,voiceTone:value.voiceTone,voiceNotes:value.voiceNotes,approvalRequired:true,schedulingAllowed:value.schedulingAllowed}});const saved=await getCuratiaOnboarding({data:{accessToken:session.access_token}});if(!saved.completed)throw new Error("Setup was saved, but Curatia could not confirm completion.");const wasCompleted=Boolean(onboarding?.completed);setOnboarding(saved);if(!wasCompleted)setView("Home");await router.invalidate();}catch(e){if(!onboarding?.completed)setAuthError(e instanceof Error?e.message:"Could not finish Curatia setup.");throw e}finally{setBusy(null)}}
 if(session&&busy==="bootstrap"&&!onboarding)return <main className="min-h-screen bg-[#f4f0e6] grid place-items-center"><div className="font-mono text-xs uppercase">Preparing your workspace…</div></main>;
 if(session&&onboarding&&!onboarding.completed)return <Onboarding initial={onboarding} busy={busy==="onboarding"} finish={finishOnboarding} error={authError}/>;
 async function signal(id:string,state:"Watch"|"Explore"|"Ignored"){setBusy(id);try{await updateSignalState({data:{id,state}});await router.invalidate();}finally{setBusy(null)}}
 async function toRadar(id:string){if(!session)return;setBusy(id);try{await moveSignalToTrendRadar({data:{accessToken:session.access_token,signalId:id}});await router.invalidate();setView("Trend Radar")}finally{setBusy(null)}}
 async function content(id:string,status:"Candidate"|"Research"|"Draft"|"Visual Ready"){setBusy(id);try{await updateContentStatus({data:{id,status}});await router.invalidate();}finally{setBusy(null)}}
 const nav:View[]=["Home","Signals","Trend Radar","Idea Tank","Content Pipeline","Editorial Studio","Calendar"];
 return <main className="min-h-screen bg-[#f4f0e6] text-[#171717]"><header className="border-b-2 border-black px-5 py-4 md:px-8"><div className="mx-auto flex max-w-[1500px] flex-wrap items-center gap-5"><button onClick={()=>setView("Home")} className="mr-2 text-left"><div className="font-mono text-[11px] font-bold uppercase tracking-[.24em]">Curatia</div><div className="font-bold">Editorial Intelligence</div></button><nav className="flex flex-1 flex-wrap gap-1">{nav.map(n=><button key={n} onClick={()=>setView(n)} className={`px-3 py-2 font-mono text-xs uppercase ${view===n?"bg-black text-[#f4f0e6]":"hover:bg-black/5"}`}>{n}</button>)}</nav><div className="relative"><button onClick={()=>{if(panel){setPanel(null);setPanelExpanded(false);setAccountOpen(true)}else setAccountOpen(x=>!x)}} className="flex items-center gap-2 border-2 border-black px-2 py-1.5"><span className="grid h-7 w-7 place-items-center overflow-hidden rounded-full bg-black text-[#f4f0e6]">{onboarding?.avatarUrl?<img src={onboarding.avatarUrl} alt="" className="h-full w-full object-cover"/>:(onboarding?.displayName||"C").slice(0,1)}</span><span className="hidden text-left text-xs font-bold md:block">{onboarding?.displayName||"Profile"}</span><span className="text-xs">▾</span></button>{accountOpen&&<div className="absolute right-0 z-20 mt-2 w-48 border-2 border-black bg-[#fbf8f0] shadow-[4px_4px_0_#171717]"><button onClick={()=>{setPanel("Profile");setPanelExpanded(false);setAccountOpen(false)}} className="block w-full px-4 py-3 text-left font-mono text-xs uppercase hover:bg-black hover:text-[#f4f0e6]">Profile</button><button onClick={()=>{setPanel("Settings");setPanelExpanded(false);setAccountOpen(false)}} className="block w-full px-4 py-3 text-left font-mono text-xs uppercase hover:bg-black hover:text-[#f4f0e6]">Settings</button><button onClick={()=>{setPanel("Integrations");setPanelExpanded(false);setAccountOpen(false)}} className="block w-full px-4 py-3 text-left font-mono text-xs uppercase hover:bg-black hover:text-[#f4f0e6]">Integrations</button>{platformOwner&&<button onClick={()=>{setPanel("Integrations");setPanelExpanded(true);setAccountOpen(false)}} className="block w-full border-t border-black px-4 py-3 text-left font-mono text-xs uppercase hover:bg-black hover:text-[#f4f0e6]">Administration</button>}<button onClick={signOut} className="block w-full border-t border-black px-4 py-3 text-left font-mono text-xs uppercase hover:bg-black hover:text-[#f4f0e6]">Sign out</button></div>}</div></div></header>
 <section className="mx-auto max-w-[1500px] px-5 py-7 md:px-8">{view==="Home"&&<Home data={data} go={setView}/>} {view==="Signals"&&<SignalsGraph graph={data.signalGraph} roleTitle={onboarding?.roleTitle||"Your role"} busy={busy} toRadar={toRadar} openRadar={()=>setView("Trend Radar")}/>} {view==="Trend Radar"&&<Radar signals={data.signals} busy={busy} move={signal}/>} {view==="Idea Tank"&&<Ideas items={data.contentItems} busy={busy} move={content}/>} {view==="Content Pipeline"&&<Pipeline items={data.contentItems}/>} {view==="Editorial Studio"&&<Studio items={data.contentItems} busy={busy} move={content}/>} {view==="Calendar"&&<Calendar items={data.contentItems}/>}</section>
 {panel&&<aside className={`fixed bottom-0 right-0 z-30 overflow-y-auto border-l-2 border-black bg-[#f4f0e6] shadow-[-6px_0_0_rgba(23,23,23,.15)] top-0 w-full md:top-[74px] ${panelExpanded?"md:left-0 md:w-full":"md:w-[48vw] md:min-w-[560px] md:max-w-[780px]"}`}><div className="sticky top-0 z-10 flex items-center justify-between border-b-2 border-black bg-[#f4f0e6] px-5 py-3"><div className="font-mono text-[10px] font-bold uppercase">Account · {panel}</div><div className="flex gap-2"><button type="button" onClick={()=>setPanelExpanded(x=>!x)} className="hidden border-2 border-black px-3 py-2 font-mono text-[10px] font-bold uppercase md:block">{panelExpanded?"↙ Collapse":"↗ Expand"}</button><button type="button" aria-label="Close panel" onClick={()=>{setPanel(null);setPanelExpanded(false)}} className="border-2 border-black px-3 py-2 font-mono text-[10px] font-bold uppercase">×</button></div></div><div className="px-5 py-6 md:px-7">{panel==="Profile"&&onboarding&&<ProfileSettings value={onboarding} save={finishOnboarding} busy={busy==="onboarding"}/>} {panel==="Settings"&&onboarding&&<EditorialSettings value={onboarding} save={finishOnboarding} busy={busy==="onboarding"}/>} {panel==="Integrations"&&session&&<Integrations items={integrations} platformOwner={platformOwner} adminCatalog={adminCatalog} accessToken={session.access_token} refresh={async()=>{setIntegrations(await getCuratiaIntegrations({data:{accessToken:session.access_token}}));if(platformOwner){const a=await getCuratiaIntegrationAdmin({data:{accessToken:session.access_token}});setAdminCatalog(a.catalog)}}}/>}</div></aside>}
 <footer className="mx-auto flex max-w-[1500px] justify-between px-5 pb-8 font-mono text-[10px] uppercase opacity-50 md:px-8"><span>Signals. Context. Decisions. Creation.</span><span>Curatia · {CURATIA_VERSION} · build {CURATIA_BUILD}</span></footer></main>;
}
function Home({data,go}:{data:CuratiaDashboard,go:(v:View)=>void}){const active=data.signals.filter(s=>["New","Watch","Explore"].includes(s.state));const approvals=data.contentItems.filter(i=>i.status==="Visual Ready").length;return <div><div className="mb-8 border-b-2 border-black pb-7"><div className="mb-3 inline-block bg-[#f2d64b] px-3 py-1 font-mono text-[11px] font-bold uppercase">Editorial workspace</div><h1 className="max-w-4xl text-4xl font-bold leading-tight md:text-6xl">What deserves your point of view?</h1><p className="mt-3 max-w-3xl opacity-65">Turn weak signals into evidence-backed ideas, then move only the strongest through production.</p></div><div className="grid gap-3 md:grid-cols-4"><Metric l="Radar health" v={String(active.length)} n="active signals" f={()=>go("Trend Radar")}/><Metric l="Canonical backlog" v={String(data.contentItems.length)} n="content items" f={()=>go("Idea Tank")}/><Metric l="Approval queue" v={String(approvals)} n="explicit approval required" f={()=>go("Editorial Studio")}/><Metric l="Evidence registry" v={String(data.sourceCount)} n="canonical sources" f={()=>go("Trend Radar")}/></div><div className="mt-8 grid gap-6 lg:grid-cols-2"><Panel t="Next up"><ContentList items={data.contentItems.slice(0,4)}/></Panel><Panel t="Radar"><div className="space-y-2">{active.slice(0,5).map(s=><SignalMini key={s.id} s={s}/>)}</div></Panel></div></div>}
function SignalsGraph({graph,roleTitle,busy,toRadar,openRadar}:{graph:CuratiaDashboard["signalGraph"];roleTitle:string;busy:string|null;toRadar:(id:string)=>void;openRadar:()=>void}){const [selected,setSelected]=useState<CuratiaSignal|null>(null);const [selectedInsight,setSelectedInsight]=useState<CuratiaDashboard["signalGraph"]["relationships"][number]|null>(null);const [mode,setMode]=useState<"Graph"|"Feed"|"Insights">("Graph");const [sort,setSort]=useState<"Newest"|"Evidence"|"Saturation"|"Sources">("Newest");const [radarFilter,setRadarFilter]=useState<"All"|"In Radar"|"Observed">("All");const evRank:Record<string,number>={Strong:3,Moderate:2,Weak:1};const satRank:Record<string,number>={High:3,Medium:2,Low:1};const nodes=graph.signals;const feedNodes=[...nodes].filter(n=>radarFilter==="All"||(radarFilter==="In Radar"?n.radar_status==="radar":n.radar_status!=="radar")).sort((a,b)=>sort==="Evidence"?(evRank[b.evidence_strength||""]||0)-(evRank[a.evidence_strength||""]||0):sort==="Saturation"?(satRank[b.saturation||""]||0)-(satRank[a.saturation||""]||0):sort==="Sources"?b.source_count-a.source_count:new Date(b.detected_at).getTime()-new Date(a.detected_at).getTime());const pos=new Map(nodes.map((n,i)=>{const a=(Math.PI*2*i/Math.max(nodes.length,1))-Math.PI/2;const ring=i%3;const radius=[31,39,24][ring];return[n.id,{x:50+Math.cos(a)*radius,y:50+Math.sin(a)*radius}]}));const connected=selected?graph.relationships.filter(r=>r.from===selected.id||r.to===selected.id):[];const insights=graph.relationships.filter(r=>r.type==="converging_with"||r.strength>=.75).sort((a,b)=>b.strength-a.strength);return <Page t="Signals" s="The living observation layer behind Trend Radar. Explore what Curatia is detecting, how signals connect, and choose what deserves editorial attention."><div className="mb-4 flex flex-wrap items-center justify-between gap-3"><div className="flex border-2 border-black">{(["Graph","Feed","Insights"] as const).map(x=><button key={x} onClick={()=>setMode(x)} className={`px-3 py-2 font-mono text-[10px] font-bold uppercase ${mode===x?"bg-black text-[#f4f0e6]":"bg-[#fbf8f0]"}`}>{x}</button>)}</div><div className="font-mono text-[10px] uppercase opacity-60">{nodes.length} signals · {graph.relationships.length} connections</div></div>{mode==="Graph"&&<div className="relative min-h-[620px] overflow-hidden border-2 border-black bg-[#171717]"><div className="absolute left-4 top-4 z-10 max-w-xs text-[#f4f0e6]"><div className="font-mono text-[9px] font-bold uppercase tracking-widest opacity-60">Live signal graph</div><p className="mt-1 text-xs opacity-60">Size reflects evidence. Lines reflect known relationships. Select a node to inspect why Curatia is tracking it.</p></div><div className="absolute inset-0 opacity-30" style={{backgroundImage:"radial-gradient(circle at center, rgba(242,214,75,.22) 0 1px, transparent 1px)",backgroundSize:"22px 22px"}}/><div className="absolute left-1/2 top-1/2 h-[78%] w-[78%] -translate-x-1/2 -translate-y-1/2 rounded-full border border-[#f2d64b]/10"/><div className="absolute left-1/2 top-1/2 h-[52%] w-[52%] -translate-x-1/2 -translate-y-1/2 rounded-full border border-[#f4f0e6]/10"/><svg viewBox="0 0 100 100" preserveAspectRatio="none" className="absolute inset-0 h-full w-full">{graph.relationships.flatMap((r,i)=>{const a=pos.get(r.from),b=pos.get(r.to);if(!a||!b)return[];const mx=(a.x+b.x)/2+(i%2?4:-4),my=(a.y+b.y)/2+(i%3-1)*5;return [<path key={"g"+i} d={`M ${a.x} ${a.y} Q ${mx} ${my} ${b.x} ${b.y}`} fill="none" stroke="#f4f0e6" strokeOpacity={.16+r.strength*.35} strokeWidth={Math.max(.12,r.strength*.32)} vectorEffect="non-scaling-stroke"/>,<circle key={"p"+i} r=".42" fill="#f2d64b"><animateMotion dur={`${3.2+(i%5)*.7}s`} repeatCount="indefinite" path={`M ${a.x} ${a.y} Q ${mx} ${my} ${b.x} ${b.y}`}/></circle>]} )}</svg>{nodes.map((n,i)=>{const p=pos.get(n.id)!;const size=n.evidence_strength==="Strong"?72:n.evidence_strength==="Moderate"?58:46;const active=selected?.id===n.id;return <button key={n.id} onClick={()=>{setSelectedInsight(null);setSelected(n)}} title={n.title} style={{left:`${p.x}%`,top:`${p.y}%`,width:size,height:size,transform:"translate(-50%,-50%)"}} className={`absolute z-10 grid place-items-center rounded-full border-2 text-center transition duration-300 hover:scale-125 ${active?"border-[#f2d64b] bg-[#f2d64b] text-black shadow-[0_0_28px_rgba(242,214,75,.85)]":"border-[#f4f0e6]/70 bg-[#171717]/90 text-[#f4f0e6] shadow-[0_0_16px_rgba(244,240,230,.18)]"}`}><span className="px-1 font-mono text-[7px] font-bold uppercase leading-tight">{n.title.length>34?n.title.slice(0,31)+"…":n.title}</span>{n.radar_status==="radar"&&<span className="absolute -right-1 -top-1 h-3 w-3 rounded-full border border-black bg-[#f2d64b]" title="In Trend Radar"/>}</button>})}<div className="absolute bottom-3 left-4 font-mono text-[8px] uppercase text-[#f4f0e6] opacity-50">● larger = stronger evidence · moving pulses = relationships · yellow = Trend Radar</div></div>}{mode==="Feed"&&<><div className="mb-3 flex flex-wrap gap-2"><select value={sort} onChange={e=>setSort(e.target.value as any)} className="border-2 border-black bg-[#fbf8f0] px-3 py-2 font-mono text-[10px] font-bold uppercase"><option>Newest</option><option>Evidence</option><option>Saturation</option><option>Sources</option></select><select value={radarFilter} onChange={e=>setRadarFilter(e.target.value as any)} className="border-2 border-black bg-[#fbf8f0] px-3 py-2 font-mono text-[10px] font-bold uppercase"><option>All</option><option>Observed</option><option>In Radar</option></select><span className="self-center font-mono text-[9px] uppercase opacity-50">{feedNodes.length} shown</span></div><div className="space-y-2">{feedNodes.map(n=><button key={n.id} onClick={()=>setSelected(n)} className="grid w-full gap-2 border border-black/20 bg-[#fbf8f0] p-4 text-left md:grid-cols-[1fr_auto]"><div><div className="font-bold">{n.title}</div><div className="mt-1 text-xs opacity-60">{n.summary}</div></div><div className="font-mono text-[9px] uppercase">{n.evidence_strength||"Unrated"} · {n.source_count} sources · {n.radar_status==="radar"?"Radar":"Observed"}</div></button>)}</div></>}{mode==="Insights"&&<div className="grid gap-3 md:grid-cols-2">{insights.length?insights.map((r,i)=>{const a=nodes.find(n=>n.id===r.from),b=nodes.find(n=>n.id===r.to);return <button key={i} onClick={()=>{setSelected(null);setSelectedInsight(r)}} className="border-2 border-black bg-[#fbf8f0] p-5 text-left shadow-[3px_3px_0_#171717] transition hover:-translate-y-0.5 hover:shadow-[5px_5px_0_#171717]"><div className="font-mono text-[9px] font-bold uppercase">Cross-signal insight · {Math.round(r.strength*100)}% relationship</div><h3 className="mt-2 text-lg font-bold">{a?.title} ↔ {b?.title}</h3><p className="mt-2 text-sm opacity-70">{r.reason||"Curatia detected a meaningful relationship between these signals."}</p><div className="mt-3 flex items-center justify-between font-mono text-[9px] uppercase opacity-50"><span>{r.type.replaceAll("_"," ")}</span><span>Open insight →</span></div></button>}):<div className="border border-black/20 p-5 text-sm opacity-60">No cross-signal insights have reached the display threshold yet.</div>}</div>}{selectedInsight&&(()=>{const a=nodes.find(n=>n.id===selectedInsight.from),b=nodes.find(n=>n.id===selectedInsight.to);return <div className="fixed inset-y-0 right-0 z-40 w-full overflow-y-auto border-l-2 border-black bg-[#f4f0e6] shadow-[-6px_0_0_rgba(23,23,23,.18)] md:w-[520px]"><div className="sticky top-0 flex items-center justify-between border-b-2 border-black bg-[#f4f0e6] p-4"><div className="font-mono text-[10px] font-bold uppercase">Cross-signal intelligence</div><button onClick={()=>setSelectedInsight(null)} className="border-2 border-black px-3 py-2 font-mono text-xs font-bold">×</button></div><div className="p-6"><div className="font-mono text-[9px] font-bold uppercase opacity-50">{selectedInsight.type.replaceAll("_"," ")} · {Math.round(selectedInsight.strength*100)}% relationship</div><h2 className="mt-2 text-2xl font-bold">Why these signals connect</h2><p className="mt-3 text-sm opacity-70">{selectedInsight.reason||"Curatia detected a meaningful relationship between these signals."}</p><div className="mt-6 space-y-3">{[a,b].filter(Boolean).map(n=><button key={n!.id} onClick={()=>{setSelectedInsight(null);setSelected(n!)}} className="block w-full border-2 border-black bg-[#fbf8f0] p-4 text-left shadow-[2px_2px_0_#171717]"><div className="font-mono text-[8px] font-bold uppercase opacity-50">Open signal intelligence</div><div className="mt-1 font-bold">{n!.title}</div><div className="mt-2 font-mono text-[8px] uppercase opacity-50">{n!.evidence_strength||"N/A"} evidence · {n!.saturation||"N/A"} saturation · {n!.source_count} sources</div></button>)}</div><div className="mt-6 border-l-2 border-[#f2d64b] pl-3"><div className="font-mono text-[9px] font-bold uppercase">Relationship label</div><p className="mt-1 text-xs opacity-70"><b>{selectedInsight.type.replaceAll("_"," ")}</b> describes how Curatia currently interprets the connection. The percentage is relationship strength, not editorial quality or confidence that this should become content.</p></div></div></div>})()}{selected&&<div className="fixed inset-y-0 right-0 z-40 w-full overflow-y-auto border-l-2 border-black bg-[#f4f0e6] shadow-[-6px_0_0_rgba(23,23,23,.18)] md:w-[520px]"><div className="sticky top-0 flex items-center justify-between border-b-2 border-black bg-[#f4f0e6] p-4"><div className="font-mono text-[10px] font-bold uppercase">Signal intelligence</div><button onClick={()=>setSelected(null)} className="border-2 border-black px-3 py-2 font-mono text-xs font-bold">×</button></div><div className="p-6"><div className="font-mono text-[9px] font-bold uppercase opacity-50">{selected.radar_status==="radar"?"In Trend Radar":"Observed signal"}</div><h2 className="mt-2 text-2xl font-bold">{selected.title}</h2>{selected.summary&&<p className="mt-3 text-sm opacity-70">{selected.summary}</p>}<div className="mt-5 grid grid-cols-3 gap-2"><SignalMetric label="Evidence" value={selected.evidence_strength||"N/A"} hint={evidenceHint(selected.evidence_strength)}/><SignalMetric label="Saturation" value={selected.saturation||"N/A"} hint={saturationHint(selected.saturation)}/><SignalMetric label="Sources" value={String(selected.source_count)} hint="Evidence sources currently linked to this signal."/></div>{selected.why_now&&<InsightBlock title="Why now" text={selected.why_now}/>} {(selected.role_impact||selected.ba_impact)&&<InsightBlock title={`${roleTitle} impact`} text={selected.role_impact||selected.ba_impact||""}/>} {selected.second_order_implication&&<InsightBlock title="Second-order implication" text={selected.second_order_implication}/>}<div className="mt-6"><div className="font-mono text-[9px] font-bold uppercase">Connected signals</div><div className="mt-2 space-y-2">{connected.length?connected.map((r,i)=>{const other=nodes.find(n=>n.id===(r.from===selected.id?r.to:r.from));return <button key={i} onClick={()=>other&&setSelected(other)} className="block w-full border border-black/20 bg-[#fbf8f0] p-3 text-left text-xs"><b>{other?.title}</b><span className="ml-2 font-mono text-[8px] uppercase opacity-50">{r.type.replaceAll("_"," ")} · {Math.round(r.strength*100)}%</span></button>}):<div className="text-xs opacity-50">No explicit relationships yet.</div>}</div></div><div className="mt-7 border-t-2 border-black pt-5">{selected.radar_status==="radar"?<button onClick={()=>{setSelected(null);openRadar()}} className="w-full bg-black px-4 py-3 font-mono text-[10px] font-bold uppercase text-[#f4f0e6]">Open in Trend Radar →</button>:<><p className="mb-3 text-xs opacity-60">You are making an explicit editorial decision that this observed signal deserves evaluation in Trend Radar. It will enter as New.</p><button disabled={busy===selected.id} onClick={()=>toRadar(selected.id)} className="w-full bg-[#f2d64b] px-4 py-3 font-mono text-[10px] font-bold uppercase disabled:opacity-40">Move to Trend Radar →</button></>}</div></div></div>}</Page>}
function InsightBlock({title,text}:{title:string;text:string}){return <div className="mt-4 border-l-2 border-[#f2d64b] pl-3"><div className="font-mono text-[9px] font-bold uppercase">{title}</div><p className="mt-1 text-xs opacity-70">{text}</p></div>}
function Radar({signals,busy,move}:{signals:CuratiaSignal[],busy:string|null,move:(id:string,s:"Watch"|"Explore"|"Ignored")=>void}){const cols=["New","Watch","Explore"] as const;return <Page t="Trend Radar" s="Evidence-backed signals. Discovery does not equal promotion."><div className="mb-5 grid gap-2 md:grid-cols-2"><RadarLegend title="Evidence strength" values={[["Strong","Multiple credible signals support the claim."],["Moderate","Useful evidence exists, but more confirmation would strengthen it."],["Weak","Early or limited evidence. Treat as a hypothesis to monitor."]]}/><RadarLegend title="Saturation" values={[["Low","Relatively open editorial space."],["Medium","The topic is visible, but a distinct angle can still stand out."],["High","Crowded conversation. A differentiated angle is essential."]]}/></div><div className="grid gap-5 lg:grid-cols-3">{cols.map(state=><section key={state}><div className="mb-3 flex items-center justify-between border-b-2 border-black pb-2"><h2 className="font-mono text-sm font-bold uppercase">{state}</h2><span className="font-mono text-xs">{signals.filter(s=>s.state===state).length}</span></div><div className="space-y-3">{signals.filter(s=>s.state===state).map(x=><SignalCard key={x.id} x={x} busy={busy===x.id} move={move}/>)}</div></section>)}</div></Page>}
function RadarLegend({title,values}:{title:string;values:string[][]}){return <details className="border border-black/20 bg-[#fbf8f0] p-3"><summary className="cursor-pointer font-mono text-[10px] font-bold uppercase">{title} · What do these labels mean?</summary><div className="mt-3 space-y-2">{values.map(([a,b])=><div key={a} className="grid grid-cols-[72px_1fr] gap-2 text-xs"><b>{a}</b><span className="opacity-65">{b}</span></div>)}</div></details>}
function SignalCard({x,busy,move}:{x:CuratiaSignal,busy:boolean,move:(id:string,s:"Watch"|"Explore"|"Ignored")=>void}){const evRank:Record<string,number>={Weak:1,Moderate:2,Strong:3};const satRank:Record<string,number>={Low:1,Medium:2,High:3};const srcDelta=x.previous_source_count===null?0:x.source_count-x.previous_source_count;const evDelta=x.previous_evidence_strength&&x.evidence_strength?(evRank[x.evidence_strength]||0)-(evRank[x.previous_evidence_strength]||0):0;const satDelta=x.previous_saturation&&x.saturation?(satRank[x.saturation]||0)-(satRank[x.previous_saturation]||0):0;const changed=srcDelta!==0||evDelta!==0||satDelta!==0;const direction=evDelta>0||srcDelta>0?"↑":evDelta<0?"↓":"→";return <article className="border border-black/20 bg-[#fbf8f0] p-4 shadow-[3px_3px_0_#171717]">{x.previous_source_count!==null&&<div className={`mb-3 flex items-center justify-between border px-2 py-1.5 font-mono text-[9px] font-bold uppercase ${changed?"border-black bg-[#f2d64b]":"border-black/15"}`}><span>{direction} Since last review</span><span>{changed?"Signal changed":"No material change"}</span></div>}<h3 className="font-bold">{x.title}</h3>{x.summary&&<p className="mt-2 text-sm opacity-70">{x.summary}</p>}{x.why_it_may_matter&&<p className="mt-3 border-l-2 border-[#f2d64b] pl-3 text-xs">{x.why_it_may_matter}</p>}<div className="mt-3 flex flex-wrap gap-2"><SignalMetric label="Evidence" value={x.evidence_strength||"N/A"} hint={evidenceHint(x.evidence_strength)}/><SignalMetric label="Saturation" value={x.saturation||"N/A"} hint={saturationHint(x.saturation)}/><SignalMetric label="Sources" value={String(x.source_count)} hint="Evidence sources currently linked to this signal."/></div>{x.previous_source_count!==null&&<div className="mt-3 border border-black/15 bg-white p-3"><div className="font-mono text-[9px] font-bold uppercase">What changed since your last review</div><ul className="mt-2 space-y-1 text-xs">{srcDelta!==0&&<li>• Sources {srcDelta>0?"+":""}{srcDelta} ({x.previous_source_count} → {x.source_count})</li>}{evDelta!==0&&<li>• Evidence {x.previous_evidence_strength} → {x.evidence_strength}</li>}{satDelta!==0&&<li>• Saturation {x.previous_saturation} → {x.saturation}</li>}{!changed&&<li>• No material evidence or saturation change detected yet.</li>}</ul></div>}<div className="mt-4 flex flex-wrap gap-2">{x.state!=="Watch"&&<Action disabled={busy} onClick={()=>move(x.id,"Watch")}>Keep watching</Action>}{x.state!=="Explore"&&<Action disabled={busy} onClick={()=>move(x.id,"Explore")}>Explore</Action>}<Action disabled={busy} onClick={()=>move(x.id,"Ignored")}>Ignore</Action></div></article>}
function SignalMetric({label,value,hint}:{label:string;value:string;hint:string}){return <span title={hint} className="border border-black/25 bg-white px-2 py-1 font-mono text-[9px] uppercase"><b>{label}:</b> {value}</span>}
function evidenceHint(v:string|null){return v==="Strong"?"Multiple credible signals support the claim.":v==="Moderate"?"Useful evidence exists, but more confirmation would strengthen it.":v==="Weak"?"Early or limited evidence. Treat as a hypothesis to monitor.":"Evidence has not been assessed yet."}
function saturationHint(v:string|null){return v==="Low"?"Relatively open editorial space.":v==="Medium"?"The topic is visible, but a distinct angle can still stand out.":v==="High"?"Crowded conversation. A differentiated angle is essential.":"Saturation has not been assessed yet."}
function Ideas({items,busy,move}:{items:CuratiaContentItem[],busy:string|null,move:(id:string,s:"Candidate")=>void}){const ideas=items.filter(i=>i.status==="Idea");return <Page t="Idea Tank" s="Canonical backlog. Promotion to Candidate is always explicit.">{ideas.length?<div className="grid gap-4 md:grid-cols-2">{ideas.map(i=><Card key={i.id} i={i}><Action disabled={busy===i.id} onClick={()=>move(i.id,"Candidate")}>Promote to Candidate</Action></Card>)}</div>:<Empty text="No items currently in Idea. Restored items are already further in the lifecycle."/>}</Page>}
function Pipeline({items}:{items:CuratiaContentItem[]}){return <Page t="Content Pipeline" s="One canonical record across the editorial lifecycle."><div className="overflow-x-auto pb-3"><div className="grid min-w-[1350px] grid-cols-9 gap-3">{lifecycle.map(st=><section key={st}><div className="mb-2 border-b-2 border-black pb-2 font-mono text-[11px] font-bold uppercase">{st} · {items.filter(i=>i.status===st).length}</div><div className="space-y-2">{items.filter(i=>i.status===st).map(i=><Card key={i.id} i={i}/>)}</div></section>)}</div></div></Page>}
function Studio({items,busy,move}:{items:CuratiaContentItem[],busy:string|null,move:(id:string,s:"Research"|"Draft"|"Visual Ready")=>void}){const a=items.filter(i=>["Candidate","Research","Draft","Visual Ready"].includes(i.status));return <Page t="Editorial Studio" s="Research, thesis, draft and visual preparation. Visual Ready is not approval."><div className="grid gap-4 lg:grid-cols-2">{a.map(i=><StudioCard key={i.id} item={i} busy={busy===i.id} move={move}/>)}</div></Page>}
function StudioCard({item,busy,move}:{item:CuratiaContentItem,busy:boolean,move:(id:string,s:"Research"|"Draft"|"Visual Ready")=>void}){const[concept,setConcept]=useState(item.visual_concept||"");const[prompt,setPrompt]=useState(item.visual_brief||"");const[saving,setSaving]=useState(false);const[generating,setGenerating]=useState(false);const[generated,setGenerated]=useState(item.final_visual_reference||"");const[saved,setSaved]=useState(false);const[visualError,setVisualError]=useState<string|null>(null);async function saveVisual(){setSaving(true);setSaved(false);setVisualError(null);try{await updateContentVisual({data:{id:item.id,visualConcept:concept,visualBrief:prompt}});setSaved(true)}catch(e){setVisualError(e instanceof Error?e.message:"Could not save visual brief.")}finally{setSaving(false)}}async function generateVisual(){setGenerating(true);setVisualError(null);try{await updateContentVisual({data:{id:item.id,visualConcept:concept,visualBrief:prompt}});const x=await generateContentVisual({data:{id:item.id,prompt,aspectRatio:"4:5"}});setGenerated(x.assetUrl);setSaved(true)}catch(e){setVisualError(e instanceof Error?e.message:"Could not generate image.")}finally{setGenerating(false)}}return <article className="border border-black/20 bg-[#fbf8f0] p-5 shadow-[2px_2px_0_#171717]"><div className="font-mono text-[10px] uppercase opacity-55">{item.id} · {item.topic||"Editorial"}</div><h3 className="mt-1 text-lg font-bold">{item.title}</h3><div className="mt-2 inline-block bg-[#f2d64b] px-2 py-1 font-mono text-[10px] font-bold uppercase">{item.status}</div>{["Draft","Visual Ready"].includes(item.status)&&<div className="mt-5 border-t border-black/20 pt-4"><div className="mb-3 font-mono text-[10px] font-bold uppercase">Visual</div><label className="font-mono text-[10px] font-bold uppercase">Visual direction</label><textarea value={concept} onChange={e=>{setConcept(e.target.value);setSaved(false)}} rows={3} placeholder="What should the visual communicate?" className="mt-1 w-full border-2 border-black bg-transparent p-3 text-sm"/><label className="mt-3 block font-mono text-[10px] font-bold uppercase">Image prompt</label><textarea value={prompt} onChange={e=>{setPrompt(e.target.value);setSaved(false)}} rows={5} placeholder="Curatia's generation prompt. Edit before creating an image." className="mt-1 w-full border-2 border-black bg-transparent p-3 text-sm"/><div className="mt-3 flex flex-wrap items-center gap-2"><Action disabled={saving||generating} onClick={()=>void saveVisual()}>{saving?"Saving…":"Save visual brief"}</Action><Action disabled={saving||generating||!prompt.trim()} onClick={()=>void generateVisual()}>{generating?"Generating…":generated?"Generate alternative":"Generate with Curatia"}</Action>{saved&&<span className="font-mono text-[9px] uppercase opacity-55">Saved</span>}</div>{visualError&&<div className="mt-3 border-l-2 border-black pl-3 text-xs">{visualError}</div>}{generated&&<div className="mt-4"><div className="font-mono text-[10px] font-bold uppercase">Selected visual</div><img src={generated} alt="" className="mt-2 max-h-80 w-full border-2 border-black object-contain"/></div>}<p className="mt-3 text-xs opacity-55">Visual direction and prompt are saved separately from the selected asset. Generations remain versioned; selecting an asset does not approve the Content Item.</p></div>}<div className="mt-4">{item.status==="Candidate"&&<Action disabled={busy} onClick={()=>move(item.id,"Research")}>Start research</Action>}{item.status==="Research"&&<Action disabled={busy} onClick={()=>move(item.id,"Draft")}>Move to draft</Action>}{item.status==="Draft"&&<Action disabled={busy} onClick={()=>move(item.id,"Visual Ready")}>Mark Visual Ready</Action>}{item.status==="Visual Ready"&&<span className="font-mono text-[10px] font-bold uppercase">Awaiting explicit approval</span>}</div></article>}
function Calendar({items}:{items:CuratiaContentItem[]}){const[now]=useState(()=>new Date());const[cursor,setCursor]=useState(()=>new Date(now.getFullYear(),now.getMonth(),1));const[selected,setSelected]=useState<CuratiaContentItem|null>(null);const y=cursor.getFullYear(),m=cursor.getMonth();const start=(new Date(y,m,1).getDay()+6)%7,days=new Date(y,m+1,0).getDate();const cells=Array.from({length:Math.ceil((start+days)/7)*7},(_,i)=>i-start+1);const dateFor=(i:CuratiaContentItem)=>i.publication_date||i.target_date;const byDay=(d:number)=>items.filter(i=>{const x=dateFor(i);if(!x)return false;const [yy,mm,dd]=x.split("-").map(Number);return yy===y&&mm===m+1&&dd===d});return <Page t="Calendar" s="Browse planned, scheduled and published content across past, present and future. Empty months remain available."><div className="mb-4 flex flex-wrap items-center justify-between gap-3"><div className="flex gap-2"><Action onClick={()=>setCursor(new Date(y,m-1,1))}>← Previous</Action><Action onClick={()=>setCursor(new Date(now.getFullYear(),now.getMonth(),1))}>Today</Action><Action onClick={()=>setCursor(new Date(y,m+1,1))}>Next →</Action></div><input aria-label="Choose month" type="month" value={`${y}-${String(m+1).padStart(2,"0")}`} onChange={e=>{const[a,b]=e.target.value.split("-").map(Number);if(a&&b)setCursor(new Date(a,b-1,1))}} className="border-2 border-black bg-transparent px-3 py-2 font-mono text-xs"/></div><h2 className="mb-3 text-2xl font-bold">{cursor.toLocaleString("en-US",{month:"long",year:"numeric"})}</h2><div className="grid grid-cols-7 border-l border-t border-black/20">{["Mon","Tue","Wed","Thu","Fri","Sat","Sun"].map(x=><div key={x} className="border-b border-r border-black/20 p-2 font-mono text-[10px] font-bold uppercase">{x}</div>)}{cells.map((d,k)=><div key={k} className="min-h-28 border-b border-r border-black/20 p-2"><div className={`mb-2 text-xs ${d<1||d>days?"opacity-20":""}`}>{d>0&&d<=days?d:""}</div>{d>0&&d<=days&&byDay(d).map(i=><button key={i.id} onClick={()=>setSelected(i)} className="mb-1 block w-full border border-black bg-[#fbf8f0] p-2 text-left text-[11px] hover:bg-[#f2d64b]"><span className="font-bold">{i.title}</span><span className="mt-1 block font-mono text-[9px] uppercase opacity-55">{i.status}{i.publication_time?` · ${i.publication_time.slice(0,5)}`:""}</span></button>)}</div>)}</div>{selected&&<div className="fixed inset-0 z-50 grid place-items-center bg-black/40 p-5" onClick={()=>setSelected(null)}><article className="w-full max-w-lg border-2 border-black bg-[#fbf8f0] p-6 shadow-[7px_7px_0_#171717]" onClick={e=>e.stopPropagation()}><div className="flex justify-between gap-4"><div><div className="font-mono text-[10px] uppercase opacity-55">{selected.status} · {selected.publishing_channel}</div><h3 className="mt-1 text-xl font-bold">{selected.title}</h3></div><button onClick={()=>setSelected(null)} aria-label="Close">✕</button></div>{selected.series&&<p className="mt-3 text-xs opacity-60">{selected.series}</p>}<p className="mt-4 text-sm">{selected.final_copy||selected.draft_copy||selected.core_idea||"No copy preview yet."}</p><div className="mt-4 font-mono text-[10px] uppercase">{dateFor(selected)}{selected.publication_time?` · ${selected.publication_time.slice(0,5)}`:""}</div></article></div>}</Page>}
function Page({t,s,children}:{t:string,s:string,children:ReactNode}){return <div><div className="mb-7 border-b-2 border-black pb-5"><h1 className="text-4xl font-bold">{t}</h1><p className="mt-2 text-sm opacity-65">{s}</p></div>{children}</div>}
function Panel({t,children}:{t:string,children:ReactNode}){return <section><h2 className="mb-3 border-b-2 border-black pb-2 font-mono text-xs font-bold uppercase">{t}</h2>{children}</section>}
function Metric({l,v,n,f}:{l:string,v:string,n:string,f:()=>void}){return <button onClick={f} className="border border-black/20 bg-[#fbf8f0] p-5 text-left shadow-[3px_3px_0_#171717]"><div className="font-mono text-[10px] uppercase opacity-60">{l}</div><div className="mt-1 text-4xl font-bold">{v}</div><div className="text-xs opacity-60">{n}</div></button>}
function Action({children,...p}:ButtonHTMLAttributes<HTMLButtonElement>){return <button {...p} className="border border-black px-2 py-1 font-mono text-[10px] font-bold uppercase hover:bg-black hover:text-[#f4f0e6] disabled:opacity-40">{children}</button>}
function Empty({text}:{text:string}){return <div className="border border-dashed border-black/30 p-8 text-sm opacity-60">{text}</div>}
function SignalMini({s}:{s:CuratiaSignal}){return <div className="border-b border-black/15 pb-2"><div className="font-semibold">{s.title}</div><div className="font-mono text-[10px] uppercase opacity-55">{s.state} · {s.evidence_strength||"Evidence n/a"}</div></div>}
function ContentList({items}:{items:CuratiaContentItem[]}){return <div className="space-y-2">{items.map(i=><Card key={i.id} i={i}/>)}</div>}
function Card({i,children}:{i:CuratiaContentItem,children?:ReactNode}){return <article className="border border-black/20 bg-[#fbf8f0] p-4 shadow-[2px_2px_0_#171717]"><div className="font-mono text-[10px] uppercase opacity-55">{i.id} · {i.topic||"Editorial"}</div><h3 className="mt-1 font-bold">{i.title}</h3><div className="mt-2 inline-block bg-[#f2d64b] px-2 py-1 font-mono text-[10px] font-bold uppercase">{i.status}</div>{children&&<div className="mt-4">{children}</div>}</article>}

function ProfileSettings({value,save,busy}:{value:CuratiaOnboarding,save:(v:CuratiaOnboarding)=>Promise<void>,busy:boolean}){const[v,setV]=useState(value);return <Page t="Profile" s="The identity and professional context Curatia uses when supporting your content."><div className="max-w-2xl space-y-4">{v.avatarUrl&&<img src={v.avatarUrl} alt="" className="h-20 w-20 rounded-full border-2 border-black object-cover"/>}<Field l="Display name" v={v.displayName} set={x=>setV({...v,displayName:x})}/><Field l="Professional role / title" v={v.roleTitle} set={x=>setV({...v,roleTitle:x})}/><label className="block font-mono text-[10px] font-bold uppercase">Positioning</label><textarea value={v.bio} onChange={e=>setV({...v,bio:e.target.value})} rows={4} className="w-full border-2 border-black bg-transparent p-3"/><div><div className="font-mono text-[10px] font-bold uppercase">Account email</div><div className="mt-2 border border-black/20 p-3 text-sm opacity-60">{v.email}</div></div><Save busy={busy} click={()=>void save(v)}/></div></Page>}
function EditorialSettings({value,save,busy}:{value:CuratiaOnboarding,save:(v:CuratiaOnboarding)=>Promise<void>,busy:boolean}){
 const[v,setV]=useState(value);const[saved,setSaved]=useState(value);const[tab,setTab]=useState("Audience");const[error,setError]=useState<string|null>(null);
 const tabs=["Audience","Discovery","Voice & Writing","Channels","Publishing","Workspace"];
 const audienceOptions=["Technology Professionals","Business Leaders","Product Professionals","Data & Analytics Professionals","Software & Engineering Professionals","AI Practitioners","Creators","Consultants","Founders","Executives","Business Analysts","Transformation Leaders"];
 const outcomeOptions=["Understand complex topics","Make better decisions","Challenge assumptions","Apply ideas in practice","Anticipate change"];
 const baselineOptions=["Technology","Business","Finance","Science","Health & Wellness","Food & Cooking","Gaming","Marketing","Design","Education","Entertainment","Sports","Culture","Lifestyle","Travel"]; const interestOptions=["Agent governance","Agent-native workflows","Agent identity & access","Agent-to-agent protocols","Context engineering","AI observability","AI governance","Human-agent collaboration","Semantic layers","MCP & agent protocols","Decision intelligence","AI-enabled BI","Data governance","Enterprise automation","Process mining","Requirements engineering"];
 const voiceOptions=["Professional","Conversational","Clear","Practical","Analytical","Thoughtful","Direct","Technical","Educational","Opinionated","Concise","Story-driven","Provocative"];
 const writingOptions=["Corporate jargon","AI-sounding language","Clickbait","Engagement bait","Excessive emojis","Hashtag walls","Overly promotional","Fake controversy","Generic motivational language"];
 const languageOptions=["English","Português (Brasil)"];
 const channelOptions=[["linkedin","LinkedIn"],["instagram","Instagram"],["x","X"],["tiktok","TikTok"],["youtube","YouTube"],["podcast","Podcast"],["newsletter","Newsletter"],["blog","Blog / Website"]];
 const flip=(x:string,a:string[])=>a.includes(x)?a.filter(i=>i!==x):[...a,x];
 const tones=v.voiceTone.split(",").map(x=>x.trim()).filter(Boolean);const writing=v.voiceNotes.split(" · ").map(x=>x.trim()).filter(Boolean);
 const dirty=JSON.stringify(v)!==JSON.stringify(saved); useEffect(()=>{if(dirty)setError(null)},[v]);
 const validation=!v.baselines.length?"Choose at least one Discovery Baseline area.":!v.primaryAudience.trim()?"Choose a primary audience.":!v.audienceOutcomes.length?"Choose at least one audience outcome.":!v.languages.length?"Choose at least one language.":!tones.length?"Choose at least one voice trait.":!v.channels.length?"Choose at least one content channel.":!v.primaryChannel?"Choose a primary channel.":!v.workspaceName.trim()?"Workspace name cannot be empty.":null;
 async function commit(){if(validation){setError(validation);return}setError(null);try{await save(v);setSaved(v)}catch(e){const raw=e instanceof Error?e.message:"";setError(/\b400\b|data request failed/i.test(raw)?"We couldn’t save these changes. Your current settings are still intact. Please try again.":raw||"Curatia could not save these settings.")}}
 return <Page t="Settings" s="How Curatia should behave for you."><div className="grid gap-6 md:grid-cols-[190px_1fr]"><nav className="space-y-1">{tabs.map(x=><button key={x} onClick={()=>{setTab(x);setError(null)}} className={`block w-full px-3 py-2 text-left font-mono text-xs uppercase ${tab===x?"bg-black text-[#f4f0e6]":"hover:bg-black/5"}`}>{x}</button>)}</nav><section className="max-w-2xl">
 {tab==="Audience"&&<div className="space-y-5"><SuggestField l="Primary audience" v={v.primaryAudience} set={x=>setV({...v,primaryAudience:x})} options={audienceOptions}/><SuggestedTagEditor l="Secondary audiences" values={v.secondaryAudiences} set={x=>setV({...v,secondaryAudiences:x})} options={audienceOptions.filter(x=>x!==v.primaryAudience)} allowCustom/><SuggestedTagEditor l="Audience outcomes" values={v.audienceOutcomes} set={x=>setV({...v,audienceOutcomes:x})} options={outcomeOptions} allowCustom/></div>}
 {tab==="Discovery"&&<div className="space-y-6"><div><div className="font-mono text-[10px] font-bold uppercase">Discovery baseline</div><p className="mt-1 text-xs opacity-60">Broad areas Curatia should explore. Add or remove areas to shape the discovery universe.</p><SuggestedTagEditor l="Explore broadly in" values={v.baselines} set={x=>setV({...v,baselines:x})} options={baselineOptions} allowCustom/></div><div><div className="font-mono text-[10px] font-bold uppercase">Your watchlist</div><p className="mt-1 text-xs opacity-60">Priority topics Curatia should pay closer attention to. Watchlist topics increase relevance without limiting discovery to them.</p><SuggestedTagEditor l="Priority topics" values={v.interests} set={x=>setV({...v,interests:x})} options={interestOptions} allowCustom/></div><div className="border border-black/20 p-4 text-xs opacity-65"><b>How discovery works:</b> Baseline provides breadth. Your Watchlist adds priority. Curatia may suggest new areas and topics as it learns, but suggestions never become selected without your confirmation.</div></div>}
 {tab==="Voice & Writing"&&<div className="space-y-6"><div><div className="font-mono text-[10px] font-bold uppercase">Preferred languages</div><p className="mt-1 text-xs opacity-60">Choose one or more supported writing languages.</p><div className="mt-2 flex flex-wrap gap-2">{languageOptions.map(x=><Choice key={x} on={v.languages.includes(x)} click={()=>setV({...v,languages:flip(x,v.languages)})}>{x}</Choice>)}</div></div><div><div className="font-mono text-[10px] font-bold uppercase">How should your content sound?</div><p className="mt-1 text-xs opacity-60">Choose from the same voice traits used in Personal Setup.</p><div className="mt-2 flex flex-wrap gap-2">{voiceOptions.map(x=><Choice key={x} on={tones.includes(x)} click={()=>{const next=flip(x,tones);setV({...v,voiceTone:next.join(", ")})}}>{x}</Choice>)}</div></div><div><div className="font-mono text-[10px] font-bold uppercase">Writing preferences · avoid</div><p className="mt-1 text-xs opacity-60">Choose the writing patterns Curatia should avoid. These are the same preferences used in Personal Setup.</p><div className="mt-2 flex flex-wrap gap-2">{writingOptions.map(x=><Choice key={x} on={writing.includes(x)} click={()=>{const next=flip(x,writing);setV({...v,voiceNotes:next.join(" · ")})}}>{x}</Choice>)}</div></div></div>}
 {tab==="Channels"&&<div className="space-y-4"><div><div className="font-mono text-[10px] font-bold uppercase">Content channels</div><p className="mt-1 text-xs opacity-60">At least one channel is required.</p><div className="mt-2 grid gap-2 md:grid-cols-2">{channelOptions.map(([k,l])=><Choice key={k} on={v.channels.includes(k)} click={()=>{const next=flip(k,v.channels);setV({...v,channels:next,primaryChannel:next.includes(v.primaryChannel)?v.primaryChannel:(next[0]||"")})}}>{l}</Choice>)}</div></div><label className="block font-mono text-[10px] font-bold uppercase">Primary channel</label><select disabled={!v.channels.length} value={v.primaryChannel} onChange={e=>setV({...v,primaryChannel:e.target.value})} className="w-full border-2 border-black bg-transparent p-3 disabled:opacity-40">{channelOptions.filter(([k])=>v.channels.includes(k)).map(([k,l])=><option key={k} value={k}>{l}</option>)}</select><p className="text-xs opacity-60">Selection configures editorial behavior. Account connections remain in Integrations.</p></div>}
 {tab==="Publishing"&&<div className="space-y-4"><div className="border-2 border-black p-4"><div className="font-mono text-[10px] font-bold uppercase">Approval policy · locked</div><div className="mt-1 font-bold">Explicit approval required</div><p className="mt-1 text-sm opacity-60">Draft and Visual Ready are never approval. Only Approved items may be scheduled or published.</p></div><Choice on={v.schedulingAllowed} click={()=>setV({...v,schedulingAllowed:!v.schedulingAllowed})}>Allow scheduling after explicit approval</Choice></div>}
 {tab==="Workspace"&&<Field l="Workspace name" v={v.workspaceName} set={x=>setV({...v,workspaceName:x})}/>}
 {error&&<div role="alert" className="mt-5 border-2 border-[#b42318] bg-[#fbf8f0] p-3 text-sm text-[#b42318]"><b>Couldn’t save.</b> {error}</div>}<Save busy={busy} disabled={!dirty||Boolean(validation)} click={()=>void commit()}/>{dirty&&validation&&<p className="mt-2 text-xs opacity-60">{validation}</p>}{!dirty&&!busy&&<p className="mt-2 font-mono text-[10px] uppercase opacity-45">All changes saved</p>}
 </section></div></Page>
}
function Integrations({items,platformOwner,adminCatalog,accessToken,refresh}:{items:CuratiaIntegration[],platformOwner:boolean,adminCatalog:CuratiaIntegrationCatalogItem[],accessToken:string,refresh:()=>Promise<void>}){const[working,setWorking]=useState<string|null>(null);const[error,setError]=useState<string|null>(null);const[adminOpen,setAdminOpen]=useState(platformOwner);const[editing,setEditing]=useState<CuratiaIntegrationCatalogItem|null>(null);const group=(category:string)=>items.filter(x=>x.category===category);async function connect(key:string){setWorking(key);setError(null);try{const r=await connectCuratiaIntegration({data:{accessToken,integrationKey:key}});if(r.redirectUrl)window.location.assign(r.redirectUrl)}catch(e){setError(e instanceof Error?e.message:"Could not start connection.");setWorking(null)}}async function disconnect(key:string,label:string){if(!window.confirm(`Disconnect ${label}? Curatia will lose access until you reconnect it. Existing Curatia content and history will not be deleted.`))return;setWorking(key);setError(null);try{await disconnectCuratiaIntegration({data:{accessToken,integrationKey:key}});await refresh()}catch(e){setError(e instanceof Error?e.message:"Could not disconnect account.")}finally{setWorking(null)}}async function verify(key:string){setWorking(key);setError(null);try{const r=await verifyCuratiaIntegrationProvider({data:{accessToken,integrationKey:key}});if(!r.ready)setError(r.message);await refresh()}catch(e){setError(e instanceof Error?e.message:"Could not verify provider.")}finally{setWorking(null)}}async function saveAdmin(x:CuratiaIntegrationCatalogItem){setWorking(x.key);setError(null);try{await saveCuratiaIntegrationCatalogItem({data:{accessToken,key:x.key,displayName:x.label,category:x.category,provider:"composio",setupStatus:x.setupStatus,capabilities:x.capabilities,description:x.description||"",toolkitSlug:x.toolkitSlug||x.key,active:x.active}});setEditing(null);await refresh()}catch(e){setError(e instanceof Error?e.message:"Could not save integration.")}finally{setWorking(null)}}const categories=Array.from(new Set(items.map(x=>x.category)));const blank:CuratiaIntegrationCatalogItem={key:"",label:"",provider:"composio",category:"Other",status:"not_connected",setupStatus:"setup_required",accountLabel:null,connectedAt:null,capabilities:[],description:"",toolkitSlug:"",authConfigRef:null,active:true};return <Page t="Integrations" s="Connect the services this workspace is allowed to use. Disconnecting access never deletes existing Curatia content or history.">{error&&<div role="alert" className="mb-4 border-2 border-[#b42318] bg-[#fbf8f0] p-3 text-sm text-[#b42318]">{error}</div>}{platformOwner&&<section className="mb-5 border-2 border-black bg-[#fbf8f0] p-4"><button type="button" onClick={()=>setAdminOpen(x=>!x)} className="flex w-full items-center justify-between text-left"><span><span className="block font-mono text-[10px] font-bold uppercase">Platform Owner · Integration Catalog</span><span className="mt-1 block text-xs opacity-65">Controls which integrations Curatia exposes to workspaces.</span></span><span>{adminOpen?"−":"+"}</span></button>{adminOpen&&<div className="mt-4"><div className="flex flex-wrap gap-2">{adminCatalog.map(x=><button type="button" key={x.key} onClick={()=>setEditing({...x})} className={`border px-3 py-2 text-left ${x.active?"border-black":"border-black/20 opacity-45"}`}><span className="block text-xs font-bold">{x.label}</span><span className="font-mono text-[9px] uppercase">{x.setupStatus==="ready"?"Ready":"Setup required"} · {x.active?"Active":"Hidden"}</span></button>)}<button type="button" onClick={()=>setEditing({...blank})} className="border-2 border-dashed border-black px-3 py-2 font-mono text-[10px] font-bold uppercase">+ Add integration</button></div>{editing&&<AdminIntegrationEditor value={editing} busy={working===editing.key} save={saveAdmin} verify={verify} close={()=>setEditing(null)}/>}</div>}</section>}<div className="grid gap-4 md:grid-cols-2">{categories.map(category=><IntegrationGroup key={category} t={category} items={group(category)} working={working} connect={connect} disconnect={disconnect}/>)}</div><p className="mt-6 max-w-3xl text-xs opacity-55">The catalog belongs to Curatia. Connections belong to this workspace. New providers appear here when enabled in the platform catalog.</p></Page>}
function AdminIntegrationEditor({value,busy,save,verify,close}:{value:CuratiaIntegrationCatalogItem,busy:boolean,save:(x:CuratiaIntegrationCatalogItem)=>void,verify:(k:string)=>void,close:()=>void}){const[v,setV]=useState(value);const isNew=!value.key;const caps=v.capabilities.join(", ");const providerReady=v.setupStatus==="ready";return <div className="mt-4 border-t-2 border-black pt-4"><div className="flex items-center justify-between"><div className="font-mono text-[10px] font-bold uppercase">{isNew?"Add integration":"Edit integration"}</div><button onClick={close} className="font-mono text-[10px] uppercase underline">Cancel</button></div><div className="mt-3 grid gap-3 md:grid-cols-2"><Field l="Integration name *" v={v.label} set={x=>setV({...v,label:x,key:isNew?v.key||x.toLowerCase().trim().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,""):v.key})}/><Field l="Category *" v={v.category} set={x=>setV({...v,category:x})}/><div><label className="mb-1 block font-mono text-[9px] font-bold uppercase">Provider *</label><div className="border-2 border-black bg-white px-3 py-2 text-sm">Composio</div></div><Field l="Toolkit / provider identifier *" v={v.toolkitSlug||""} set={x=>setV({...v,toolkitSlug:x})}/><div className="md:col-span-2"><Field l="Capabilities * · comma separated" v={caps} set={x=>setV({...v,capabilities:x.split(",").map(y=>y.trim()).filter(Boolean)})}/></div><div className="md:col-span-2"><Field l="Description · optional" v={v.description||""} set={x=>setV({...v,description:x})}/></div></div><details className="mt-3 border-t border-black/15 pt-3"><summary className="cursor-pointer font-mono text-[9px] font-bold uppercase">Advanced</summary><div className="mt-2 max-w-sm"><Field l="Integration key" v={v.key} set={x=>setV({...v,key:x.toLowerCase().replace(/[^a-z0-9_-]/g,"")})}/></div></details><div className="mt-4 grid gap-3 md:grid-cols-2"><div className="border border-black/20 p-3"><div className="font-mono text-[9px] font-bold uppercase">Catalog visibility</div><button type="button" onClick={()=>setV({...v,active:!v.active})} className={`mt-2 border-2 border-black px-3 py-2 font-mono text-[10px] font-bold uppercase ${v.active?"bg-[#f2c94c]":"bg-white"}`}>{v.active?"● Active":"○ Hidden"}</button><p className="mt-2 text-[10px] opacity-50">Controls whether workspaces can see this integration.</p></div><div className="border border-black/20 p-3"><div className="font-mono text-[9px] font-bold uppercase">Provider status</div><div className="mt-2 font-mono text-[10px] font-bold uppercase">{providerReady?"● Ready":"○ Setup required"}</div><p className="mt-2 text-[10px] opacity-50">{providerReady?"Provider configuration has been verified.":"Verify the provider configuration before this integration can be connected."}</p>{!isNew&&<button disabled={busy} onClick={()=>verify(value.key)} className="mt-3 border-2 border-black px-3 py-2 font-mono text-[10px] font-bold uppercase disabled:opacity-30">{busy?"Verifying…":"Verify provider"}</button>}</div></div><div className="mt-4 flex flex-wrap gap-2"><button disabled={busy||!v.key||!v.label||!v.category||!v.toolkitSlug||v.capabilities.length===0} onClick={()=>save(v)} className="bg-black px-4 py-2 font-mono text-[10px] font-bold uppercase text-[#f4f0e6] disabled:opacity-30">{busy?"Saving…":"Save integration"}</button><button onClick={close} className="border-2 border-black px-4 py-2 font-mono text-[10px] font-bold uppercase">Cancel</button></div><p className="mt-2 text-[10px] opacity-50">{isNew?"Save the catalog entry first, then verify its provider configuration. ":""}Provider credentials stay server-side. Provider status is determined by verification, not manually selected.</p></div>}
function IntegrationGroup({t,items,working,connect,disconnect}:{t:string,items:CuratiaIntegration[],working:string|null,connect:(k:string)=>void,disconnect:(k:string,l:string)=>void}){return <section className="border border-black/20 bg-[#fbf8f0] p-5 shadow-[2px_2px_0_#171717]"><h2 className="font-mono text-xs font-bold uppercase">{t}</h2>{items.map(x=><div key={x.key} className="mt-3 border-t border-black/15 pt-3"><div className="flex items-start justify-between gap-4"><div><div className="font-semibold">{x.label}</div>{x.accountLabel&&<div className="font-mono text-[9px] uppercase opacity-45">{x.accountLabel}</div>}<div className="mt-1 text-[10px] opacity-50">{x.capabilities.join(" · ")}</div></div><span className={`font-mono text-[10px] font-bold uppercase ${x.status==="connected"?"":"opacity-45"}`}>{x.status==="connected"?"● Connected":"○ Not connected"}</span></div><div className="mt-3">{x.setupStatus!=="ready"?<span className="font-mono text-[10px] uppercase opacity-45">Provider setup required</span>:x.status==="connected"?<button disabled={working===x.key} onClick={()=>disconnect(x.key,x.label)} className="font-mono text-[10px] font-bold uppercase underline disabled:opacity-40">{working===x.key?"Disconnecting…":"Disconnect"}</button>:<button disabled={working===x.key} onClick={()=>connect(x.key)} className="border-2 border-black px-3 py-2 font-mono text-[10px] font-bold uppercase disabled:opacity-40">{working===x.key?"Opening…":"Connect"}</button>}</div></div>)}</section>}
function TagEditor({l,values,set}:{l:string,values:string[],set:(v:string[])=>void}){const[x,setX]=useState("");return <div><label className="font-mono text-[10px] font-bold uppercase">{l}</label><div className="mt-2 flex gap-2"><input value={x} onChange={e=>setX(e.target.value)} className="flex-1 border-2 border-black bg-transparent p-3"/><button onClick={()=>{if(x.trim()&&!values.some(v=>v.toLowerCase()===x.trim().toLowerCase())){set([...values,x.trim()]);setX("")}}} className="border-2 border-black px-4 font-mono text-xs font-bold uppercase">Add</button></div><div className="mt-2 flex flex-wrap gap-2">{values.map(y=><button key={y} onClick={()=>set(values.filter(i=>i!==y))} className="bg-[#f2d64b] px-3 py-2 text-xs">{y} ×</button>)}</div></div>}
function SuggestedTagEditor({l,values,set,options,allowCustom=false}:{l:string,values:string[],set:(v:string[])=>void,options:string[],allowCustom?:boolean}){const[x,setX]=useState("");const[known,setKnown]=useState(()=>Array.from(new Set([...options,...values])));useEffect(()=>{setKnown(k=>Array.from(new Set([...k,...options,...values])))},[options,values]);const id="suggest-"+l.toLowerCase().replace(/[^a-z0-9]+/g,"-");const add=()=>{const y=x.trim();if(y&&(allowCustom||known.includes(y))&&!values.some(v=>v.toLowerCase()===y.toLowerCase())){setKnown(k=>Array.from(new Set([...k,y])));set([...values,y]);setX("")}};const available=known.filter(o=>!values.includes(o));return <div><label className="font-mono text-[10px] font-bold uppercase">{l}</label><div className="mt-2 flex gap-2"><input list={id} value={x} onChange={e=>setX(e.target.value)} onKeyDown={e=>{if(e.key==="Enter"){e.preventDefault();add()}}} placeholder="Type to search or add" className="flex-1 border-2 border-black bg-transparent p-3"/><datalist id={id}>{available.map(o=><option key={o} value={o}/>)}</datalist><button type="button" onClick={add} className="border-2 border-black px-4 font-mono text-xs font-bold uppercase">Add</button></div><div className="mt-2 flex flex-wrap gap-2">{values.map(y=><button type="button" key={y} onClick={()=>set(values.filter(i=>i!==y))} className="bg-[#f2d64b] px-3 py-2 text-xs">{y} ×</button>)}</div>{available.length>0&&<div className="mt-3 flex flex-wrap gap-2">{available.map(o=><button type="button" key={o} onClick={()=>set([...values,o])} className="border border-black/30 px-2 py-1 text-xs hover:bg-black hover:text-[#f4f0e6]">+ {o}</button>)}</div>}</div>}
function Save({busy,click,disabled=false}:{busy:boolean,click:()=>void,disabled?:boolean}){return <button disabled={busy||disabled} onClick={click} className="mt-6 bg-black px-5 py-3 font-mono text-xs font-bold uppercase text-[#f4f0e6] disabled:cursor-not-allowed disabled:opacity-30">{busy?"Saving…":"Save changes"}</button>}

function Onboarding({initial,busy,finish,error}:{initial:CuratiaOnboarding,busy:boolean,finish:(v:CuratiaOnboarding)=>Promise<void>,error:string|null}){const[step,setStep]=useState(0);const[v,setV]=useState(initial);const[interest,setInterest]=useState("");const[secondary,setSecondary]=useState("");const[territory,setTerritory]=useState("");const steps=["Welcome","About you","Audience","Discovery interests","Content channels","Voice & writing","Publishing"];const patch=(x:Partial<CuratiaOnboarding>)=>setV(p=>({...p,...x}));const flip=(x:string,list:string[])=>list.includes(x)?list.filter(i=>i!==x):[...list,x];const contentFocusOptions=["Artificial Intelligence","Agentic AI","Data & Analytics","Software & Engineering","Cybersecurity","Cloud & Infrastructure","Automation","Product & Delivery","Digital Transformation","Technology Strategy"];const baselineAreas=["Technology","Business","Finance","Science","Health & Wellness","Food & Cooking","Gaming","Marketing","Design","Education","Entertainment","Sports","Culture","Lifestyle","Travel"];const interests=["Agent governance","Agent-native workflows","Agent identity & access","Agent-to-agent protocols","Context engineering","AI observability","AI governance","Human-agent collaboration","Semantic layers","MCP & agent protocols","Decision intelligence","AI-enabled BI","Data governance","Enterprise automation","Process mining","Requirements engineering"];const audienceOptions=["Technology Professionals","Business Leaders","Product Professionals","Data & Analytics Professionals","Software & Engineering Professionals","AI Practitioners","Creators","Consultants","Founders","Executives","Business Analysts","Transformation Leaders"];const outcomes=["Understand complex topics","Make better decisions","Challenge assumptions","Apply ideas in practice","Anticipate change"];const channels=[["linkedin","LinkedIn"],["instagram","Instagram"],["x","X"],["tiktok","TikTok"],["youtube","YouTube"],["podcast","Podcast"],["newsletter","Newsletter"],["blog","Blog / Website"]];const languages=["English","Português (Brasil)"];const canFinish=Boolean(v.displayName&&v.channels.length&&v.primaryChannel&&v.languages.length);return <main className="min-h-screen bg-[#f4f0e6] text-[#171717] grid place-items-center px-5 py-8"><section className="w-full max-w-2xl border-2 border-black bg-[#fbf8f0] p-7 shadow-[7px_7px_0_#171717]"><div className="flex justify-between font-mono text-[10px] font-bold uppercase"><span>Curatia · Personal setup</span><span>{step+1}/{steps.length}</span></div><div className="mt-3 h-1 bg-black/10"><div className="h-full bg-black" style={{width:`${((step+1)/steps.length)*100}%`}}/></div><h1 className="mt-6 text-3xl font-bold">{steps[step]}</h1>{step===0&&<div className="mt-5"><h2 className="text-2xl font-bold">Welcome to Curatia.</h2><p className="mt-2 opacity-70">Your editorial intelligence workspace is ready. Personalize Curatia now, or start with neutral defaults and refine them later in Settings.</p><button type="button" onClick={()=>{patch({contentTerritories:[],primaryAudience:"",secondaryAudiences:[],audienceOutcomes:[],baselines:["Technology"],interests:[],languages:["English"],voiceTone:"Professional, Conversational, Clear, Practical",voiceNotes:"",approvalRequired:true,schedulingAllowed:false});setStep(4)}} className="mt-5 border-2 border-black px-4 py-3 font-mono text-xs font-bold uppercase">Use defaults for now</button><p className="mt-2 text-xs opacity-55">You will still choose at least one content channel. Curatia does not guess where you publish.</p></div>}{step===1&&<div className="mt-5 space-y-4"><Field l="Display name" v={v.displayName} set={x=>patch({displayName:x})}/><SuggestField l="Professional role / title" v={v.roleTitle} set={x=>patch({roleTitle:x})} options={["Product Manager","Software Engineer","Data Analyst","Designer","Consultant","Founder","Marketing Professional","Technology Leader","Business Analyst","Researcher","Creator","Executive"]}/><div><label className="block font-mono text-[10px] font-bold uppercase">What do you want to create content about?</label><p className="mt-1 text-xs opacity-60">Choose your Content Focus areas. You can refine them later in Settings.</p><div className="mt-3 flex flex-wrap gap-2">{contentFocusOptions.map(x=><Choice key={x} on={v.contentTerritories.includes(x)} click={()=>patch({contentTerritories:flip(x,v.contentTerritories)})}>{x}</Choice>)}</div><div className="mt-3 flex gap-2"><input list="curatia-content-focus" value={territory} onChange={e=>setTerritory(e.target.value)} placeholder="Type to search or add your own" className="flex-1 border-2 border-black bg-transparent p-3"/><datalist id="curatia-content-focus">{contentFocusOptions.filter(x=>!v.contentTerritories.includes(x)).map(x=><option key={x} value={x}/>)}</datalist><button type="button" onClick={()=>{const x=territory.trim();if(x&&!v.contentTerritories.includes(x)){patch({contentTerritories:[...v.contentTerritories,x]});setTerritory("")}}} className="border-2 border-black px-4 font-mono text-xs font-bold uppercase">Add</button></div></div><div><label className="block font-mono text-[10px] font-bold uppercase">Your perspective · optional</label><p className="mt-1 text-xs opacity-60">Is there a particular point of view you want Curatia to bring to these topics? Leave this blank and Curatia can help refine it over time.</p><textarea value={v.bio} onChange={e=>patch({bio:e.target.value})} rows={4} placeholder="How AI changes the way organizations analyze, design and make decisions, with a focus on the evolving role of Business Analysis." className="mt-2 w-full border-2 border-black bg-transparent p-3"/></div></div>}{step===2&&<div className="mt-5 space-y-5"><SuggestField l="Who is your content primarily for?" v={v.primaryAudience} set={x=>patch({primaryAudience:x})} options={audienceOptions}/><div><label className="font-mono text-[10px] font-bold uppercase">Secondary audiences · optional</label><div className="mt-2 flex gap-2"><input list="curatia-secondary-audiences" value={secondary} onChange={e=>setSecondary(e.target.value)} placeholder="Type to search or add your own" className="flex-1 border-2 border-black bg-transparent p-3"/><datalist id="curatia-secondary-audiences">{audienceOptions.filter(x=>x!==v.primaryAudience&&!v.secondaryAudiences.includes(x)).map(x=><option key={x} value={x}/>)}</datalist><button onClick={()=>{if(secondary.trim()&&secondary.trim()!==v.primaryAudience&&!v.secondaryAudiences.some(x=>x.toLowerCase()===secondary.trim().toLowerCase())){patch({secondaryAudiences:[...v.secondaryAudiences,secondary.trim()]});setSecondary("")}}} className="border-2 border-black px-4 font-mono text-xs font-bold uppercase">Add</button></div><div className="mt-2 flex flex-wrap gap-2">{v.secondaryAudiences.map(x=><button key={x} onClick={()=>patch({secondaryAudiences:v.secondaryAudiences.filter(i=>i!==x)})} className="bg-[#f2d64b] px-3 py-2 text-xs">{x} ×</button>)}</div></div><div><label className="font-mono text-[10px] font-bold uppercase">What should they get from your content?</label><div className="mt-2 grid gap-2 md:grid-cols-2">{outcomes.map(x=><Choice key={x} on={v.audienceOutcomes.includes(x)} click={()=>patch({audienceOutcomes:flip(x,v.audienceOutcomes)})}>{x}</Choice>)}</div></div></div>}{step===3&&<div className="mt-5"><p className="mb-4 text-sm opacity-65">Choose broad areas Curatia should explore, then the priority topics it should watch more closely.</p><div className="font-mono text-[10px] font-bold uppercase">Discovery baseline</div><div className="mt-2 flex flex-wrap gap-2">{baselineAreas.map(x=><Choice key={x} on={v.baselines.includes(x)} click={()=>patch({baselines:flip(x,v.baselines)})}>{x}</Choice>)}</div><div className="mt-5 font-mono text-[10px] font-bold uppercase">Your watchlist</div><div className="mt-2 flex flex-wrap gap-2">{interests.map(x=><Choice key={x} on={v.interests.includes(x)} click={()=>patch({interests:flip(x,v.interests)})}>{x}</Choice>)}</div><div className="mt-4 flex gap-2"><input value={interest} onChange={e=>setInterest(e.target.value)} list="curatia-interests" placeholder="Search or add custom interest" className="flex-1 border-2 border-black bg-transparent p-3"/><datalist id="curatia-interests">{interests.filter(x=>!v.interests.includes(x)).map(x=><option key={x} value={x}/>)}</datalist><button type="button" onClick={()=>{if(interest.trim()&&!v.interests.some(x=>x.toLowerCase()===interest.trim().toLowerCase())){patch({interests:[...v.interests,interest.trim()]});setInterest("")}}} className="border-2 border-black px-4 font-mono text-xs font-bold uppercase">Add</button></div></div>}{step===4&&<div className="mt-5"><p className="mb-4 text-sm opacity-65">Where do you want to create content? Select the channels Curatia should consider when developing content. Account connections come later.</p><div className="grid gap-2 md:grid-cols-2">{channels.map(([k,l])=><Choice key={k} on={v.channels.includes(k)} click={()=>{const next=flip(k,v.channels);patch({channels:next,primaryChannel:next.includes(v.primaryChannel)?v.primaryChannel:(next[0]||"")})}}>{l}</Choice>)}</div><label className="mt-5 block font-mono text-[10px] font-bold uppercase">Which is your primary channel?</label><select value={v.primaryChannel} onChange={e=>patch({primaryChannel:e.target.value})} className="mt-2 w-full border-2 border-black bg-transparent p-3">{channels.filter(([k])=>v.channels.includes(k)).map(([k,l])=><option key={k} value={k}>{l}</option>)}</select></div>}{step===5&&<div className="mt-5 space-y-5"><div><label className="font-mono text-[10px] font-bold uppercase">Preferred language(s)</label><div className="mt-2 grid gap-2 md:grid-cols-2">{languages.map(x=><Choice key={x} on={v.languages.includes(x)} click={()=>patch({languages:flip(x,v.languages)})}>{x}</Choice>)}</div></div><div><label className="font-mono text-[10px] font-bold uppercase">How should your content sound?</label><p className="mt-1 text-xs opacity-60">Choose a few qualities. You can refine these later in Settings.</p><div className="mt-2 flex flex-wrap gap-2">{["Professional","Conversational","Clear","Practical","Analytical","Thoughtful","Direct","Technical","Educational","Opinionated","Concise","Story-driven","Provocative"].map(x=>{const a=v.voiceTone.split(",").map(y=>y.trim()).filter(Boolean);return <Choice key={x} on={a.includes(x)} click={()=>patch({voiceTone:(a.includes(x)?a.filter(y=>y!==x):[...a,x]).join(", ")})}>{x}</Choice>})}</div></div><div><label className="font-mono text-[10px] font-bold uppercase">Writing preferences</label><p className="text-xs opacity-60">Choose common patterns to avoid, or add your own note later in Settings.</p><div className="mt-2 flex flex-wrap gap-2">{["Corporate jargon","AI-sounding language","Clickbait","Engagement bait","Excessive emojis","Hashtag walls","Overly promotional","Fake controversy","Generic motivational language"].map(x=>{const a=v.voiceNotes.split(" · ").map(y=>y.trim()).filter(Boolean);return <Choice key={x} on={a.includes(x)} click={()=>patch({voiceNotes:(a.includes(x)?a.filter(y=>y!==x):[...a,x]).join(" · ")})}>{x}</Choice>})}</div></div></div>}{step===6&&<div className="mt-5"><div><h2 className="text-2xl font-bold">You stay in control of publishing.</h2><p className="mt-2 text-sm opacity-65">Curatia can research, draft, create visuals and prepare content. Nothing is published without your explicit approval.</p></div><div className="mt-5 flex flex-wrap gap-2 font-mono text-[10px] font-bold uppercase">{["Draft","Visual Ready","Approved","Scheduled","Published"].map(x=><span key={x} className={x==="Approved"?"bg-[#f2d64b] px-2 py-2":"border border-black/30 px-2 py-2"}>{x}</span>)}</div><div className="mt-5 space-y-3"><p><b>✓ Approval is always explicit.</b> <span className="text-sm opacity-60">A finished draft or visual is not approval.</span></p><p><b>✓ Scheduling comes after approval.</b> <span className="text-sm opacity-60">Only approved Content Items can be scheduled.</span></p><p><b>✓ Channel connections are separate.</b> <span className="text-sm opacity-60">Connecting an account never authorizes unapproved publishing.</span></p></div></div>}{error&&<div className="mt-5 border-2 border-black bg-[#f2d64b] p-3 text-sm">{error}</div>}<div className="mt-8 flex justify-between border-t border-black/20 pt-5"><button disabled={step===0||busy} onClick={()=>setStep(s=>s-1)} className="font-mono text-xs font-bold uppercase disabled:opacity-30">Back</button>{step<steps.length-1?<button onClick={()=>setStep(s=>s+1)} className="bg-black px-5 py-3 font-mono text-xs font-bold uppercase text-[#f4f0e6]">Continue</button>:<button disabled={busy||!canFinish} onClick={()=>void finish(v).catch(()=>{})} className="bg-black px-5 py-3 font-mono text-xs font-bold uppercase text-[#f4f0e6] disabled:opacity-40">{busy?"Saving…":"Finish setup"}</button>}</div></section></main>}
function SuggestField({l,v,set,options}:{l:string,v:string,set:(x:string)=>void,options:string[]}){const id="curatia-"+l.toLowerCase().replace(/[^a-z0-9]+/g,"-");return <div><label className="block font-mono text-[10px] font-bold uppercase">{l}</label><input list={id} value={v} onChange={e=>set(e.target.value)} placeholder="Type to search or enter your own" className="mt-2 w-full border-2 border-black bg-transparent p-3"/><datalist id={id}>{options.filter(x=>x.toLowerCase()!==v.trim().toLowerCase()).map(x=><option key={x} value={x}/>)}</datalist></div>}
function Field({l,v,set,placeholder}:{l:string,v:string,set:(x:string)=>void,placeholder?:string}){return <div><label className="block font-mono text-[10px] font-bold uppercase">{l}</label><input value={v} onChange={e=>set(e.target.value)} placeholder={placeholder} className="mt-2 w-full border-2 border-black bg-transparent p-3"/></div>}
function Choice({on,click,children}:{on:boolean,click:()=>void,children:ReactNode}){return <button type="button" onClick={click} className={`border-2 border-black p-3 text-left text-sm ${on?"bg-black text-[#f4f0e6]":"bg-transparent"}`}>{children}</button>}

function Login({busy,message,send,oauth}:{busy:boolean,message:string|null,send:(email:string)=>Promise<void>,oauth:(provider:"github"|"google")=>void}){const[email,setEmail]=useState("");return <main className="min-h-screen bg-[#f4f0e6] text-[#171717] grid place-items-center px-5"><section className="w-full max-w-md border-2 border-black bg-[#fbf8f0] p-7 shadow-[7px_7px_0_#171717]"><div className="font-mono text-[11px] font-bold uppercase tracking-[.24em]">Curatia</div><h1 className="mt-2 text-4xl font-bold">Editorial Intelligence</h1><p className="mt-3 text-sm opacity-65">Sign in to your editorial workspace. Your first successful login creates the Curatia owner workspace automatically.</p><div className="mt-7"><button type="button" onClick={()=>oauth("google")} className="w-full border-2 border-black px-3 py-3 font-mono text-xs font-bold uppercase hover:bg-black hover:text-[#f4f0e6]">Continue with Google</button></div><div className="my-5 flex items-center gap-3"><span className="h-px flex-1 bg-black/20"/><span className="font-mono text-[10px] uppercase opacity-50">or email</span><span className="h-px flex-1 bg-black/20"/></div><form onSubmit={e=>{e.preventDefault();if(email)void send(email)}}><label className="font-mono text-[10px] font-bold uppercase">Email</label><input required type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@example.com" className="mt-2 w-full border-2 border-black bg-[#f4f0e6] px-3 py-3 outline-none"/><button disabled={busy} className="mt-3 w-full bg-black px-4 py-3 font-mono text-xs font-bold uppercase text-[#f4f0e6] disabled:opacity-50">{busy?"Sending…":"Send sign-in link"}</button></form>{message&&<p className="mt-4 border-l-2 border-[#f2d64b] pl-3 text-xs">{message}</p>}<Link to="/" className="mt-6 inline-block font-mono text-[10px] uppercase underline underline-offset-4">Back to guilhermecosta.tech</Link></section></main>}
